from collections import deque


def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        v = queue.pop()
        order.append(v)
        for n in sorted(graph.adjacency[v]):
            if n not in visited:
                visited.add(n)
                queue.append(n)
    return order
